# A relative link to another Markdown page, which the site serves as HTML.
MARKDOWN_LINK = re.compile(r"^([^:#]+)\.md(#.*)?$")


class DocumentParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.ids: set[str] = set()
        self.references: list[str] = []

    def handle_starttag(self, _tag: str, attrs: list[tuple[str, str | None]]) -> None:
        values = dict(attrs)
        if values.get("id"):
            self.ids.add(values["id"] or "")
        for name in ("href", "src"):
            if values.get(name):
                self.references.append(values[name] or "")

    handle_startendtag = handle_starttag


def slugify(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode()
    normalized = normalized.lower().strip()
    normalized = re.sub(r"[^a-z0-9 _-]", "", normalized)
    return re.sub(r"[ -]+", "-", normalized).strip("-") or "section"


def inline_text(token) -> str:
    if not token.children:
        return token.content
    return "".join(child.content for child in token.children if child.type in {"text", "code_inline"})


def markdown() -> MarkdownIt:
    md = MarkdownIt("commonmark", {"html": True, "linkify": False})
    md.enable("table")
    md.enable("strikethrough")
    return md


def render(source: Path) -> dict:
    """Render one Markdown document for the reading layout.

    The first heading becomes the page title, so it is dropped from the body.
    Sections, lists and tables take the classes the API pages use, every
    heading gets an id, and links to other Markdown pages point at their HTML.
    """
    md = markdown()
    tokens = md.parse(source.read_text(encoding="utf-8"))
    if not tokens or tokens[0].type != "heading_open" or tokens[0].tag != "h1":
        raise ValueError(f"{source.name} must start with its title")
    title = inline_text(tokens[1])
    tokens = tokens[3:]

    headings: list[tuple[int, str, str]] = []
    used: dict[str, int] = {}
    anchors: set[str] = set()
    local: list[str] = []
    for index, token in enumerate(tokens):
        if token.type in {"bullet_list_open", "ordered_list_open"}:
            token.attrSet("class", "list")
        elif token.type == "table_open":
            token.attrSet("class", "spec")
        elif token.type == "heading_open":
            if token.tag == "h2":
                token.attrSet("class", "part")
            text = inline_text(tokens[index + 1])
            base = slugify(text)
            seen = used.get(base, 0)
            used[base] = seen + 1
            anchor = base if seen == 0 else f"{base}-{seen}"
            token.attrSet("id", anchor)
            anchors.add(anchor)
            headings.append((int(token.tag[1]), text, anchor))
        if token.type != "inline" or not token.children:
            continue
        for child in token.children:
            if child.type != "link_open":
                continue
            href = child.attrGet("href") or ""
            if href.startswith("#"):
                local.append(href[1:])
            match = MARKDOWN_LINK.match(href)
            if match:
                child.attrSet("href", f"{match[1]}.html{match[2] or ''}")
            elif urlsplit(href).scheme in {"http", "https"}:
                child.attrSet("rel", "noopener noreferrer")

    missing = sorted(set(local) - anchors)
    if missing:
        raise ValueError(f"{source.name} links to missing headings: {', '.join(missing)}")
    sections = "\n".join(
        f'        <li><a href="#{html.escape(anchor)}">{html.escape(text)}</a></li>'
        for level, text, anchor in headings
        if level == 2
    )
    return {"title": title, "tokens": tokens, "sections": sections, "md": md}


def spec_facts(tokens: list) -> tuple[str, list]:
    """Turn the `**Version:** 3.0.0` lines before the first section into the facts line."""
    end = next(i for i, t in enumerate(tokens) if t.type == "heading_open")
    facts: list[str] = []
    for token in tokens[:end]:
        if token.type != "inline":
            continue
        for line in token.content.splitlines():
            match = re.fullmatch(r"\*\*(.+?)\*\*:?\s+(.+?)\s*", line.strip())
            if match:
                facts.append(f"{match.group(1).rstrip(':')} {match.group(2)}")
    if not facts:
        raise ValueError("SPEC.md must list its version and status under the title")
    items = "\n".join(f"<li>{html.escape(fact)}</li>" for fact in facts)
    return f'<ul class="facts">\n{items}\n</ul>\n', tokens[end:]


def pages(root: str, here: str) -> str:
    def item(href: str, label: str) -> str:
        current = ' class="here" aria-current="page"' if href == here else ""
        return f'        <li><a href="{root}{href}"{current}>{label}</a></li>'

    lines = [item("spec/index.html", "Specification"), '        <li class="toc-group">Extensions</li>']
    lines += [item(f"spec/extensions/{name}.html", EXTENSION_TITLES[name]) for name in EXTENSIONS]
    return "\n".join(lines)


def spec_page() -> str:
    rendered = render(SPEC_DIR / "SPEC.md")
    facts, tokens = spec_facts(rendered["tokens"])
    md = rendered["md"]
    lede = (
        '<p class="lede">The normative definition of a TACO dataset, rendered from '
        '<a href="https://github.com/asterisk-labs/taco/blob/main/docs/spec/SPEC.md" rel="noopener noreferrer">'
        "<code>SPEC.md</code></a>. Each extension it names has its own page, listed on the left.</p>\n"
    )
    return PAGE.format(
        title="TACO · Specification",
        description="The TACO specification: the contract, the metadata model and the FOLDER, ZIP and TACOCAT containers.",
        root="../",
        source="docs/spec/SPEC.md",
        pages=pages("../", "spec/index.html"),
        heading="Specification",
        facts=facts,
        lede=lede,
        body=md.renderer.render(tokens, md.options, {}),
        sections=rendered["sections"],
    )


def extension_page(name: str) -> str:
    rendered = render(SPEC_DIR / "extensions" / f"{name}.md")
    md = rendered["md"]
    title = html.escape(rendered["title"])
    return PAGE.format(
        title=f"TACO · {title}",
        description=f"The {title} of the TACO specification.",
        root="../../",
        source=f"docs/spec/extensions/{name}.md",
        pages=pages("../../", f"spec/extensions/{name}.html"),
        heading=title,
        facts="",
        lede="",
        body=md.renderer.render(rendered["tokens"], md.options, {}),
        sections=rendered["sections"],
    )


def write_spec(spec_root: Path) -> None:
    documents = sorted(path.stem for path in (SPEC_DIR / "extensions").glob("*.md"))
    if sorted(EXTENSIONS) != documents:
        raise ValueError(f"the extension list does not match spec/extensions: {', '.join(documents)}")
    (spec_root / "index.html").write_text(spec_page(), encoding="utf-8")
    for name in EXTENSIONS:
        (spec_root / "extensions" / f"{name}.html").write_text(extension_page(name), encoding="utf-8")


def prepare_output(output: Path, *, clean: bool) -> None:
    if output.exists() and not output.is_dir():
        raise ValueError(f"output path is not a directory: {output}")
    if not output.exists():
        return
    if any(output.iterdir()):
        if not clean:
            raise FileExistsError(f"output directory is not empty: {output}")
        if output.name != "_site":
            raise ValueError(f"refusing to clean output not named _site: {output}")
        shutil.rmtree(output)
        return
    output.rmdir()


def assert_required(output: Path) -> None:
    missing = [name for name in REQUIRED if not (output / name).is_file()]
    if missing:
        raise FileNotFoundError(f"site build is missing: {', '.join(missing)}")


def assert_local_links(output: Path) -> None:
    root = output.resolve()
    documents: dict[Path, DocumentParser] = {}
    for page in output.rglob("*.html"):
        document = DocumentParser()
        document.feed(page.read_text(encoding="utf-8"))
        documents[page.resolve()] = document

    errors: list[str] = []
    for page, document in documents.items():
        for reference in document.references:
            parsed = urlsplit(reference)
            if parsed.scheme or parsed.netloc or reference.startswith(("mailto:", "data:", "javascript:")):
                continue
            target = page if not parsed.path else (page.parent / unquote(parsed.path)).resolve()
            if not target.is_relative_to(root):
                errors.append(f"{page.relative_to(root)} escapes the site: {reference}")
                continue
            if target.is_dir():
                target /= "index.html"
            if not target.is_file():
                errors.append(f"{page.relative_to(root)} has missing target: {reference}")
                continue
            if parsed.fragment and target.suffix == ".html":
                linked = documents.get(target.resolve())
                if linked is None or unquote(parsed.fragment) not in linked.ids:
                    errors.append(f"{page.relative_to(root)} has missing anchor: {reference}")
    if errors:
        raise ValueError("; ".join(errors))


def build(output: Path, *, clean: bool = False) -> None:
    prepare_output(output, clean=clean)
    if not DOCS_SOURCE.is_dir():
        raise FileNotFoundError(f"missing documentation source: {DOCS_SOURCE}")
    shutil.copytree(DOCS_SOURCE, output, ignore=IGNORED)
    for name, source in SOURCES.items():
        if not source.is_dir():
            raise FileNotFoundError(f"missing site source: {source}")
        shutil.copytree(source, output / name, ignore=IGNORED)
    write_spec(output / "spec")
    (output / ".nojekyll").touch()
    assert_required(output)
    assert_local_links(output)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=ROOT / "_site")
    parser.add_argument("--clean", action="store_true", help="replace an existing _site")
    parser.add_argument(
        "--sync-spec",
        action="store_true",
        help="also write the rendered specification pages into docs/spec",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    try:
        if args.sync_spec:
            write_spec(SPEC_DIR)
        build(args.output.resolve(), clean=args.clean)
    except (FileExistsError, FileNotFoundError, ValueError) as exc:
        print(f"site build failed: {exc}", file=sys.stderr)
        return 1
    print(f"built the website in {args.output.resolve()}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
